style.css:
@-moz-document domain("roblox.com") {
/* Set the main background color for the body and the core page container */
  body,
  .light-theme,
  .dark-theme,
  .content-area,
  .container-main,
  .games-page-container {
    background-color: #1a1a3e !important;
    color: #e0e0e0 !important;
  }

  /* Style main headers and text */
  h1,
  h2,
  h3,
  .text,
  .text-link {
    color: #e36e33 !important;
  }

  /* Change the background of the top navigation bar */
  .navbar-header,
  .rbx-header {
    background-color: #1a1a3e !important;
    border-bottom-color: #e36e33 !important;
  }

  /* Style buttons and interactive elements with the accent color */
  .btn-common-play-game-lg,
  .btn-control-lg,
  .btn-primary-md,
  .btn-primary-lg,
  .btn-control-md,
  .btn-control-sm {
    background-color: #e36e33 !important;
    border-color: #e36e33 !important;
    color: #ffffff !important;
    transition: background-color 0.2s ease;
  }

  /* Add hover effect for buttons */
  .btn-common-play-game-lg:hover,
  .btn-primary-md:hover,
  .btn-primary-lg:hover,
  .btn-control-md:hover,
  .btn-control-sm:hover {
    background-color: #e38e53 !important;
  }

  /* Adjust card backgrounds (e.g., game listings) */
  .game-card-container,
  .roblox-card {
    background-color: #2b2b4d !important;
    border-color: #3e3e60 !important;
    transition: border-color 0.2s ease;
  }

  /* Highlight card on hover */
  .game-card-container:hover,
  .roblox-card:hover {
    border-color: #e36e33 !important;
  }

  /* Style sidebar and other sections */
  .roblox-grid-container {
    background-color: #1a1a3e !important;
  }

  /* Adjust input fields and search bars */
  input[type="text"],
  input[type="password"],
  .input-field {
    background-color: #3e3e60 !important;
    border: 1px solid #5e5e80 !important;
    color: #ffffff !important;
  }

  /* Make links stand out */
  a:link,
  a:visited,
  a:hover,
  a:active {
    color: #e36e33 !important;
  }

  /* Ensure text is readable on all backgrounds */
  .text-dark {
    color: #e0e0e0 !important;
  }
}
